// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.ui.stateimport android.content.Contextimport android.content.Intentimport android.content.IntentFilterimport android.net.ConnectivityManagerimport android.net.NetworkCapabilitiesimport android.os.BatteryManagerimport android.os.PowerManagerimport com.roshan.persona.brain.context.DeviceContextimport com.roshan.persona.brain.context.NetworkTypeimport com.roshan.persona.brain.context.PrivacySettingsimport com.roshan.persona.brain.context.ResponseLengthimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.context.ThermalStatusimport com.roshan.persona.brain.context.UserContextimport com.roshan.persona.brain.memory.MemoryInterfaceimport com.roshan.persona.brain.orchestrator.BrainOrchestratorimport com.roshan.persona.brain.persona.Personaimport com.roshan.persona.brain.persona.ResponseStyleimport com.roshan.persona.brain.persona.Toneimport com.roshan.persona.brain.persona.Verbosityimport com.roshan.persona.brain.persona.Vocabularyimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Dispatchersimport kotlinx.coroutines.SupervisorJobimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlowimport kotlinx.coroutines.launchimport timber.log.Timberimport java.text.SimpleDateFormatimport java.util.Dateimport java.util.Localeimport javax.inject.Injectimport javax.inject.Singleton/** * RealUiStateProvider — wires Module 2 (Brain) + Module 3 (Memory) to UI. * * All initial [MutableStateFlow] values are NEUTRAL — they represent * "unknown / not yet measured" rather than fake values. They are * immediately refreshed by [refreshBrainStats] (called in [init]), * which in turn calls [refreshDeviceStatus] to populate real device * metrics via Android system APIs. * * **Integration v3:** Hilt-injectable. Provided via [com.roshan.persona.ui.di.UiModule]. * Brain + Memory are non-null (Hilt guarantees their presence). */@Singletonclass RealUiStateProvider @Inject constructor(    @dagger.hilt.android.qualifiers.ApplicationContext private val appContext: Context,    private val brainOrchestrator: BrainOrchestrator,    private val memoryInterface: MemoryInterface,) : UiStateProvider {    /**     * Application-scoped coroutine scope.     *     * Uses [SupervisorJob] so a single failure in one child doesn't cancel siblings.     * Tied to the application process (not an Activity) — survives configuration     * changes. Released implicitly when the process dies.     *     * We do NOT cancel this scope on Activity destroy because:     *   1. RealUiStateProvider is a Hilt @Singleton — outlives any Activity.     *   2. Background refresh (memory/brain stats) should continue across config changes.     *   3. The SupervisorJob ensures a single failure doesn't cascade.     */    private val scope = CoroutineScope(Dispatchers.Main.immediate + SupervisorJob())    // ─── Brain (Module 2) ────────────────────────────────────────────    // 0 = "brain not yet probed" — replaced by refreshBrainStats() in init {}    private val _brainHealth = MutableStateFlow(0)    override val brainHealthPercent: StateFlow<Int> = _brainHealth.asStateFlow()    private val _activeLayer = MutableStateFlow<String?>(null)    override val activeBrainLayer: StateFlow<String?> = _activeLayer.asStateFlow()    // Empty map = "no layer activity yet" — replaced when brain processes first request    private val _layerActivity = MutableStateFlow<Map<String, Float>>(emptyMap())    override val brainLayerActivity: StateFlow<Map<String, Float>> = _layerActivity.asStateFlow()    private val _lastLatency = MutableStateFlow(0L)    override val lastBrainLatencyMs: StateFlow<Long> = _lastLatency.asStateFlow()    private val _lastCost = MutableStateFlow(0f)    override val lastBrainCostUsd: StateFlow<Float> = _lastCost.asStateFlow()    private val _lastTokens = MutableStateFlow(0)    override val lastBrainTokens: StateFlow<Int> = _lastTokens.asStateFlow()    // Em dash = "no layer has handled a request yet"    private val _lastLayerHandled = MutableStateFlow("—")    override val lastBrainLayerHandled: StateFlow<String> = _lastLayerHandled.asStateFlow()    // ─── Memory (Module 3) ───────────────────────────────────────────    private val _memoryCount = MutableStateFlow(0)    override val memoryCount: StateFlow<Int> = _memoryCount.asStateFlow()    private val _episodicCount = MutableStateFlow(0)    override val episodicCount: StateFlow<Int> = _episodicCount.asStateFlow()    private val _semanticCount = MutableStateFlow(0)    override val semanticCount: StateFlow<Int> = _semanticCount.asStateFlow()    private val _memoryStorage = MutableStateFlow(0f)    override val memoryStorageMb: StateFlow<Float> = _memoryStorage.asStateFlow()    private val _recentMemories = MutableStateFlow<List<MemoryItem>>(emptyList())    override val recentMemories: StateFlow<List<MemoryItem>> = _recentMemories.asStateFlow()    private val _knownFacts = MutableStateFlow<List<String>>(emptyList())    override val knownFacts: StateFlow<List<String>> = _knownFacts.asStateFlow()    // ─── LLM (Module 4) — populated by LlmModule's LocalModelManager when a model loads ──    private val _localLlmLoaded = MutableStateFlow(false)    override val localLlmLoaded: StateFlow<Boolean> = _localLlmLoaded.asStateFlow()    private val _localLlmModel = MutableStateFlow<String?>(null)    override val localLlmModelName: StateFlow<String?> = _localLlmModel.asStateFlow()    private val _cloudProvider = MutableStateFlow<String?>(null)    override val cloudProviderName: StateFlow<String?> = _cloudProvider.asStateFlow()    private val _monthlyCost = MutableStateFlow(0f)    override val monthlyCostUsd: StateFlow<Float> = _monthlyCost.asStateFlow()    // Default budget — matches UserContext.monthlyLlmBudgetUsd default    private val _monthlyBudget = MutableStateFlow(10f)    override val monthlyBudgetUsd: StateFlow<Float> = _monthlyBudget.asStateFlow()    // ─── Voice (Module 5) — populated by VoiceModule when voice pipeline activates ──    // "Disconnected" = honest initial state, replaced when VoiceModule boots    private val _voiceState = MutableStateFlow("Disconnected")    override val voiceState: StateFlow<String> = _voiceState.asStateFlow()    private val _wakeWordActive = MutableStateFlow(false)    override val wakeWordActive: StateFlow<Boolean> = _wakeWordActive.asStateFlow()    // "Not loaded" = honest initial state, replaced when STT engine initializes    private val _sttEngine = MutableStateFlow("Not loaded")    override val sttEngineName: StateFlow<String> = _sttEngine.asStateFlow()    private val _ttsEngine = MutableStateFlow("Not loaded")    override val ttsEngineName: StateFlow<String> = _ttsEngine.asStateFlow()    private val _speakerCount = MutableStateFlow(0)    override val speakerCount: StateFlow<Int> = _speakerCount.asStateFlow()    private val _noiseCancellation = MutableStateFlow(false)    override val noiseCancellationActive: StateFlow<Boolean> = _noiseCancellation.asStateFlow()    // ─── Foundation (Module 1) — populated by refreshDeviceStatus() in init {} ──    // 0 = "battery not yet probed" — replaced by refreshDeviceStatus() within milliseconds    private val _battery = MutableStateFlow(0)    override val batteryLevel: StateFlow<Int> = _battery.asStateFlow()    private val _charging = MutableStateFlow(false)    override val isCharging: StateFlow<Boolean> = _charging.asStateFlow()    // "Not probed" = honest initial state, replaced by refreshDeviceStatus()    private val _thermal = MutableStateFlow("Not probed")    override val thermalStatus: StateFlow<String> = _thermal.asStateFlow()    private val _network = MutableStateFlow("Not probed")    override val networkStatus: StateFlow<String> = _network.asStateFlow()    private val _privacyMode = MutableStateFlow(false)    override val privacyModeEnabled: StateFlow<Boolean> = _privacyMode.asStateFlow()    // ─── Conversation ────────────────────────────────────────────────    private val _conversation = MutableStateFlow<List<ConversationItem>>(emptyList())    override val conversationHistory: StateFlow<List<ConversationItem>> = _conversation.asStateFlow()    private val _transcription = MutableStateFlow<String?>(null)    override val liveTranscription: StateFlow<String?> = _transcription.asStateFlow()    init {        // Launch suspend functions in coroutine scope — populates real values        // from Brain, Memory, and Android system APIs (battery/thermal/network).        scope.launch { refreshBrainStats() }        scope.launch { refreshMemoryData() }    }    override suspend fun sendVoiceInput(text: String) {        _conversation.value = _conversation.value + ConversationItem(            speaker = "You",            text = text,            isNous = false,        )        _voiceState.value = "PROCESSING"        _activeLayer.value = "L4"        try {            val response = brainOrchestrator.process(                userInput = text,                sessionId = SessionId("ui-session"),                activePersona = createDefaultPersona(),                userContext = createDefaultUserContext(),                deviceContext = createDefaultDeviceContext(),            )            _lastLatency.value = response.totalDurationMs            _lastCost.value = response.costUsd            _lastTokens.value = response.tokensGenerated            _lastLayerHandled.value = response.handledBy.displayName            _conversation.value = _conversation.value + ConversationItem(                speaker = "NOUS",                text = response.message,                isNous = true,                layer = response.handledBy.displayName,                latency = "${response.totalDurationMs}ms",            )        } catch (e: Exception) {            Timber.e(e, "Brain processing failed")            _conversation.value = _conversation.value + ConversationItem(                speaker = "NOUS",                text = "Error: ${e.message}",                isNous = true,                layer = "Error",                latency = "0ms",            )        }        _voiceState.value = "IDLE"        _activeLayer.value = null    }    override suspend fun refreshMemoryData() {        try {            val factsResult = memoryInterface.getUserFacts()            if (factsResult is com.roshan.persona.common.Result.Success) {                _semanticCount.value = factsResult.data.size                _knownFacts.value = factsResult.data.map { "${it.key}: ${it.value}" }            }            val recallResult = memoryInterface.recall("recent", k = 10)            if (recallResult is com.roshan.persona.common.Result.Success) {                val memories = recallResult.data                _memoryCount.value = memories.size                _episodicCount.value = memories.count { it.type.name == "EPISODIC" }                val sdf = SimpleDateFormat("HH:mm", Locale.getDefault())                _recentMemories.value = memories.map { mem ->                    MemoryItem(                        content = mem.content,                        timestamp = sdf.format(Date(mem.timestamp.toEpochMilli())),                        importance = mem.importance,                        type = mem.type.name,                    )                }            }            _memoryStorage.value = calculateMemoryStorageMb()        } catch (e: Exception) {            Timber.e(e, "Memory load failed")        }    }    override suspend fun refreshBrainStats() {        // Brain (50) + Memory (30) + LLM (10) + Voice (10) = max 100        // Both Brain + Memory are guaranteed non-null (Hilt-injected).        var health = 50  // Brain present        health += 30     // Memory present        refreshDeviceStatus()        _brainHealth.value = health    }    /**     * Refresh real device status from Android system APIs.     *     * Reads:     *   - Battery level + charging state via [Intent.ACTION_BATTERY_CHANGED] sticky broadcast     *   - Thermal status via [PowerManager.getCurrentThermalState]     *   - Network type via [ConnectivityManager.getNetworkCapabilities]     *     * All values are written into the corresponding [MutableStateFlow]s so any     * UI observer immediately sees the real device state. Failures are logged     * to Timber with tag "NOUS.UI" and silently leave the previous value in     * place (which is "Not probed" on first call — clearly honest to the user).     */    private fun refreshDeviceStatus() {        try {            // Battery level + charging status via BatteryManager sticky broadcast.            val batteryIntent = appContext.registerReceiver(                null,                IntentFilter(Intent.ACTION_BATTERY_CHANGED),            )            if (batteryIntent != null) {                val level = batteryIntent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1)                val scale = batteryIntent.getIntExtra(BatteryManager.EXTRA_SCALE, -1)                if (level >= 0 && scale > 0) {                    _battery.value = (level * 100) / scale                }                val status = batteryIntent.getIntExtra(BatteryManager.EXTRA_STATUS, -1)                _charging.value = status == BatteryManager.BATTERY_STATUS_CHARGING ||                    status == BatteryManager.BATTERY_STATUS_FULL            }            // Thermal status via PowerManager.            val powerManager = appContext.getSystemService(Context.POWER_SERVICE) as? PowerManager            if (powerManager != null) {                val thermalState = powerManager.getCurrentThermalStatus()                _thermal.value = when (thermalState) {                    PowerManager.THERMAL_STATUS_NONE -> "Cool"                    PowerManager.THERMAL_STATUS_LIGHT -> "Light"                    PowerManager.THERMAL_STATUS_MODERATE -> "Moderate"                    PowerManager.THERMAL_STATUS_SEVERE -> "Severe"                    PowerManager.THERMAL_STATUS_CRITICAL -> "Critical"                    PowerManager.THERMAL_STATUS_EMERGENCY -> "Emergency"                    else -> "Unknown"                }            }            // Network status via ConnectivityManager.            val connManager = appContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager            if (connManager != null) {                val network = connManager.activeNetwork                val caps = connManager.getNetworkCapabilities(network)                _network.value = when {                    caps == null -> "Offline"                    caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) -> "WiFi"                    caps.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR) -> "Cellular"                    caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET) -> "Ethernet"                    else -> "Unknown"                }            }        } catch (e: Exception) {            Timber.tag("NOUS.UI").w(e, "Failed to refresh device status")        }    }    /**     * Calculate actual memory storage size from Room database file.     *     * Reads the real on-disk size of `nous.db` (the encrypted Room database)     * via [Context.getDatabasePath]. Returns 0.0 if the file does not yet     * exist (first launch before any memory is written).     */    private fun calculateMemoryStorageMb(): Float {        return try {            val dbFile = appContext.getDatabasePath("nous.db")            if (dbFile.exists()) {                dbFile.length().toFloat() / (1024f * 1024f)            } else {                0f            }        } catch (e: Exception) {            0f        }    }    // ─── Default context builders (for brain processing) ─────────────    private fun createDefaultPersona(): Persona {        return Persona(            id = "atlas",            displayName = "Atlas",            systemPromptTemplate = "You are Atlas, a steadfast AI companion.",            skillPreferences = emptyMap(),            responseStyle = ResponseStyle(                tone = Tone.WITTY,                verbosity = Verbosity.BALANCED,                useEmoji = false,                vocabulary = Vocabulary.TECHNICAL,            ),        )    }    private fun createDefaultUserContext(): UserContext {        return UserContext(            userId = "nous-user",            displayName = "User",            preferredLanguage = Locale.ENGLISH,            preferredResponseLength = ResponseLength.BALANCED,            skillPreferences = emptyMap(),            privacySettings = PrivacySettings(),            monthlyLlmBudgetUsd = 10f,            monthlyLlmSpentUsd = 0f,        )    }    private fun createDefaultDeviceContext(): DeviceContext {        // Read live device state from our own StateFlows — these were populated        // by refreshDeviceStatus() in init {}, so we never feed stale defaults        // into the Brain's DeviceContext.        return DeviceContext(            thermalStatus = when (_thermal.value) {                "Cool" -> ThermalStatus.NONE                "Light" -> ThermalStatus.LIGHT                "Moderate" -> ThermalStatus.MODERATE                "Severe" -> ThermalStatus.SEVERE                "Critical" -> ThermalStatus.CRITICAL                "Emergency" -> ThermalStatus.EMERGENCY                else -> ThermalStatus.NONE            },            availableRamMb = getAvailableRamMb(),            batteryLevel = _battery.value,            isCharging = _charging.value,            isOnline = _network.value != "Offline",            networkType = when (_network.value) {                "WiFi" -> NetworkType.WIFI                "Cellular" -> NetworkType.CELLULAR_4G  // ConnectivityManager doesn't distinguish 4G/5G                "Ethernet" -> NetworkType.WIFI  // treat Ethernet as WiFi-class (suitable for cloud LLM)                else -> NetworkType.NONE            },            gpuAvailable = false,            gpuVramMb = 0,        )    }    /** Read available RAM via ActivityManager.MemoryInfo — real device probe. */    private fun getAvailableRamMb(): Int {        return try {            val activityManager = appContext.getSystemService(Context.ACTIVITY_SERVICE)                as? android.app.ActivityManager            val memInfo = android.app.ActivityManager.MemoryInfo()            activityManager?.getMemoryInfo(memInfo)            (memInfo.availMem / (1024 * 1024)).toInt()        } catch (e: Exception) {            2048  // Conservative fallback only if ActivityManager probe fails        }    }}
